import * as React from "react"
import type { VariantProps } from "class-variance-authority"

import { cn } from "@/registry/base-nova/lib/utils"
import { fieldVariants } from "@/registry/base-nova/ui/field"

/**
 * local-override の独自契約(base-nova には form アイテムが存在しない)。
 * upstream の docs/forms ガイドに倣い、Field プリミティブの上に最小2部品で再設計する:
 * - FormItem は Field と同じ DOM 構造(data-slot="field")を描き、invalid で
 *   data-invalid を出す。data-slot を "field" のまま維持するのは、Field の
 *   クラス群が group/field 名前空間や has-[>[data-slot=field-content]] 等の
 *   兄弟セレクタに依存するため
 * - ラベル・説明は FieldLabel / FieldDescription を直接使う(docs/forms の組み立て方)
 * - FormError は upstream の FieldError セマンティクス(1件は平文・複数は
 *   リスト・空なら非描画)を、Rails の文字列配列で受ける形にしたもの
 * aria-invalid / aria-describedby / htmlFor-id の紐付けは呼び出し側の責務。
 */
function FormItem({
  className,
  invalid = false,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & { invalid?: boolean } & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation}
      data-invalid={invalid}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  )
}

function FormError({
  className,
  children,
  errors,
  ...props
}: React.ComponentProps<"div"> & { errors?: Array<string | null | undefined> }) {
  const uniqueMessages = [...new Set(errors ?? [])].filter((message) => message)
  if (!children && uniqueMessages.length === 0) {
    return null
  }

  return (
    <div
      role="alert"
      data-slot="field-error"
      className={cn("text-sm font-normal text-destructive", className)}
      {...props}
    >
      {!children && uniqueMessages.length > 1 ? (
        <ul className={cn("ml-4 flex list-disc flex-col gap-1")}>
          {uniqueMessages.map((message, index) => (
            <li key={index}>{message}</li>
          ))}
        </ul>
      ) : (
        children ?? uniqueMessages[0]
      )}
    </div>
  )
}

export { FormError, FormItem }
